package com.witchersbestiary.test;
import com.witchersbestiary.fist.*;import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;import net.minecraft.test.*;import net.minecraft.util.math.*;import net.minecraft.item.*;
public final class FistFightTests implements FabricGameTest{
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21b")
 public void personalNpcCooldownPersistence(TestContext c){
  var rewards=new FistRewards();var a=java.util.UUID.randomUUID();var b=java.util.UUID.randomUUID();var npc=java.util.UUID.randomUUID();var other=java.util.UUID.randomUUID();
  c.assertTrue(rewards.reserveWin(a,npc,100,12),"A first victory");
  c.assertTrue(rewards.reserveWin(b,npc,101,12),"B independently paid for same NPC");
  c.assertTrue(!rewards.reserveWin(a,npc,102,12)&&rewards.pending(a)==12,"Duplicate cannot add crowns");
  c.assertTrue(rewards.reserveWin(a,other,102,12),"Other NPC of same tier independent");
  var saved=rewards.writeNbt(new net.minecraft.nbt.NbtCompound(),c.getWorld().getRegistryManager());
  var restored=FistRewards.read(saved,c.getWorld().getRegistryManager());
  c.assertTrue(restored.pending(a)==24&&restored.pending(b)==12,"Pending sums persisted");
  c.assertTrue(!restored.reserveWin(a,npc,24099,12),"Cooldown survives reload");
  c.assertTrue(restored.reserveWin(a,npc,24100,12)&&!restored.reserveWin(a,npc,24100,12),"Expiry permits exactly one reservation");
  c.assertTrue(!restored.reserveWin(a,npc,Long.MAX_VALUE,12)&&!restored.reserve(a,-1),"Reject invalid reservation");c.complete();
 }
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21b")
 public void heldGuardCannotResetCounterWindow(TestContext c){var f=started();c.assertTrue(f.act(false,FistFightSession.Action.BLOCK),"Guard starts");for(int i=0;i<8;i++)f.tick();double stamina=f.opponent.stamina;c.assertTrue(!f.act(false,FistFightSession.Action.BLOCK)&&f.opponent.actionTicks==8&&f.opponent.stamina==stamina,"Repeated guard cannot reset timing or cost");c.assertTrue(f.releaseBlock(false),"Guard releases");c.complete();}
 @GameTest(templateName="witchersbestiary:notice_board_arena",batchId="stage21b",tickLimit=40)
 public void twoPlayersWinSameNpc(TestContext c){
  for(var type:java.util.List.<net.minecraft.entity.EntityType<? extends FistNpc>>of(FistRegistry.NOVICE,FistRegistry.ROCK_TROLL)){
   var n=npc(c,type,3);var a=player(c,n);var b=player(c,n);int expected=n.winReward();
   for(var p:java.util.List.of(a,b)){
    FistFights.invite(p,n);c.assertTrue(FistFights.confirm(p,n),"Independent confirmed bout against same NPC");var fight=FistFights.active(p).fight();for(int t=0;t<60;t++)fight.tick();fight.opponent.health=1;c.assertTrue(fight.act(true,FistFightSession.Action.QUICK),"Winning action accepted");for(int t=0;t<4;t++)fight.tick();fight.hit(true,true,true);FistFights.tick(p.getServer());
    c.assertTrue(FistFights.active(p)==null&&p.getInventory().count(com.witchersbestiary.economy.Currency.CROWN)==expected,"Each player receives own crowns for "+type);
    FistFights.action(p,FistFightSession.Action.QUICK);FistFights.tick(p.getServer());c.assertTrue(p.getInventory().count(com.witchersbestiary.economy.Currency.CROWN)==expected,"Post-finish requests cannot duplicate payout");
   }
   a.discard();b.discard();n.discard();
  }
  c.complete();
 }
 @GameTest(templateName="witchersbestiary:notice_board_arena",batchId="stage21c",tickLimit=40)
 public void trollRegistrationAndNonfatalBout(TestContext c){
  var troll=c.spawnEntity(FistRegistry.ROCK_TROLL,3,2,3);var p=player(c,troll);c.assertTrue(troll.getTarget()==null&&troll.winReward()==90,"Neutral registered troll with separate reward");
  FistFights.invite(p,troll);c.assertTrue(FistFights.confirm(p,troll),"Shared confirmation works");var f=FistFights.active(p).fight();c.assertTrue(f.opponent.health==180&&f.opponent.maxStamina==140&&f.player.maxStamina==140&&f.player.stamina==140&&f.opponent.heavyDamageMultiplier>1,"Troll bout balance");float hp=troll.getHealth();for(int i=0;i<60;i++)f.tick();f.opponent.health=1;f.act(true,FistFightSession.Action.QUICK);for(int i=0;i<4;i++)f.tick();f.hit(true,true,true);FistFights.tick(p.getServer());c.assertTrue(troll.isAlive()&&troll.getHealth()==hp&&troll.pose().equals("knockout"),"Nonfatal troll knockout");c.assertTrue(p.getInventory().count(com.witchersbestiary.economy.Currency.CROWN)==90,"Troll pays crowns");p.discard();troll.discard();c.complete();
 }
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21c")
 public void trollMountainAndCaveSpawnIntegration(TestContext c){
  var registry=c.getWorld().getRegistryManager().get(net.minecraft.registry.RegistryKeys.BIOME);
  for(var key:java.util.List.of(net.minecraft.world.biome.BiomeKeys.STONY_PEAKS,net.minecraft.world.biome.BiomeKeys.DRIPSTONE_CAVES)){
   var biome=registry.getEntry(key).orElseThrow();c.assertTrue(biome.isIn(RockTrollSpawns.HABITATS),"Extensible habitat includes "+key.getValue());
   c.assertTrue(biome.value().getSpawnSettings().getSpawnEntries(net.minecraft.entity.SpawnGroup.CREATURE).getEntries().stream().anyMatch(e->e.type==FistRegistry.ROCK_TROLL),"Natural spawn list includes troll in "+key.getValue());
  }
  c.assertTrue(!com.witchersbestiary.contracts.procedural.ContractSpecies.ENTITIES.containsValue("rock_troll"),"Troll excluded from procedural hunts");c.complete();
 }
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21c")
 public void trollHudMaximumSurvivesPacketCodec(TestContext c){var buffer=new net.minecraft.network.RegistryByteBuf(io.netty.buffer.Unpooled.buffer(),c.getWorld().getRegistryManager());try{var state=new FistPackets.State(true,7,0,180,70,140,100,"entity.witchersbestiary.rock_troll","HEAVY");FistPackets.State.CODEC.encode(buffer,state);var decoded=FistPackets.State.CODEC.decode(buffer);c.assertTrue(decoded.equals(state)&&decoded.stamina()/decoded.maxStamina()==.5f,"HUD maximum and other state fields round-trip");}finally{buffer.release();}c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21c")
 public void trollFistTelegraphsMatchItsAnimations(TestContext c){var troll=c.spawnEntity(FistRegistry.ROCK_TROLL,2,2,2);var f=started();troll.configureBout(f);float actual=troll.getHealth();c.assertTrue(troll.fightPose(FistFightSession.Action.QUICK).equals("wild_quick")&&troll.fightPose(FistFightSession.Action.HEAVY).equals("wild_heavy"),"Separate troll clips");f.act(false,FistFightSession.Action.QUICK);for(int i=0;i<7;i++)f.tick();c.assertTrue(!f.contact(false),"Troll quick preparation remains readable");f.tick();c.assertTrue(f.contact(false)&&f.hit(false,true,true),"Quick contact at8");for(int i=0;i<12;i++)f.tick();c.assertTrue(f.opponent.action==FistFightSession.Action.IDLE,"Quick recovery ends at20");f.act(false,FistFightSession.Action.HEAVY);for(int i=0;i<17;i++)f.tick();c.assertTrue(!f.contact(false),"Troll heavy preparation");f.tick();double before=f.player.health;c.assertTrue(f.hit(false,true,true)&&Math.abs(before-f.player.health-30.8)<.0001,"Heavy contact at18 with troll damage");c.assertTrue(troll.getHealth()==actual,"Bout never changes real health");troll.discard();c.complete();}
 private FistFightSession started(){var f=new FistFightSession();for(int i=0;i<60;i++)f.tick();return f;}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21b")
 public void quickHeavyBlockAndCounter(TestContext c){var f=started();c.assertTrue(f.act(true,FistFightSession.Action.QUICK)&&f.act(false,FistFightSession.Action.BLOCK),"Actions accepted");for(int i=0;i<4;i++)f.tick();double hp=f.opponent.health;c.assertTrue(f.hit(true,true,true)&&f.opponent.health<hp&&f.opponent.health>hp-9,"Frontal block reduces damage");double once=f.opponent.health;c.assertTrue(!f.hit(true,true,true)&&f.opponent.health==once,"One contact per attack");c.assertTrue(f.opponent.counterTicks>0&&f.act(false,FistFightSession.Action.COUNTER),"Timely block counter window");for(int i=0;i<5;i++)f.tick();c.assertTrue(f.hit(false,true,true)&&f.player.health<100,"Counter damages virtual health");var heavy=started();heavy.act(true,FistFightSession.Action.HEAVY);for(int i=0;i<13;i++)heavy.tick();c.assertTrue(!heavy.contact(true),"Heavy has fourteen tick preparation");heavy.tick();heavy.hit(true,true,false);c.assertTrue(heavy.opponent.health==78,"Heavy contact damage");c.complete();}
 @GameTest(templateName=FabricGameTest.EMPTY_STRUCTURE,batchId="stage21b")
 public void dodgeAndStaminaLimits(TestContext c){var f=started();f.act(true,FistFightSession.Action.QUICK);f.act(false,FistFightSession.Action.DODGE);for(int i=0;i<4;i++)f.tick();c.assertTrue(!f.hit(true,true,true)&&f.opponent.health==100&&f.opponent.counterTicks>0,"Timed dodge avoids virtual damage");for(int i=0;i<6;i++)f.tick();c.assertTrue(f.act(false,FistFightSession.Action.COUNTER),"Dodge recovery leaves usable counter window");var exhausted=started();int attacks=0;for(int i=0;i<8;i++){if(exhausted.act(true,FistFightSession.Action.HEAVY))attacks++;for(int t=0;t<28;t++)exhausted.tick();}c.assertTrue(attacks<8&&exhausted.player.stamina>=0,"Stamina prevents unlimited heavy attacks");for(int i=0;i<200;i++)exhausted.tick();c.assertTrue(exhausted.player.stamina==100,"Bounded regeneration");c.complete();}
 private <T extends FistNpc> T npc(TestContext c,net.minecraft.entity.EntityType<T> type,int x){for(int xx=x-3;xx<x+4;xx++)for(int z=0;z<8;z++)c.setBlockState(new BlockPos(xx,1,z),net.minecraft.block.Blocks.STONE);return c.spawnEntity(type,x,2,3);}
 private net.minecraft.server.network.ServerPlayerEntity player(TestContext c,FistNpc n){var p=c.createMockCreativeServerPlayerInWorld();p.getInventory().clear();p.setStackInHand(net.minecraft.util.Hand.OFF_HAND,ItemStack.EMPTY);p.refreshPositionAndAngles(n.getX()-2,n.getY(),n.getZ(),-90,0);c.assertTrue(p.isAlive()&&n.isAlive()&&p.getWorld()==n.getWorld()&&!p.isSpectator()&&p.getMainHandStack().isEmpty()&&p.getOffHandStack().isEmpty()&&p.squaredDistanceTo(n)<=16,"Bout fixture alive="+p.isAlive()+" npc="+n.isAlive()+" sameWorld="+(p.getWorld()==n.getWorld())+" spectator="+p.isSpectator()+" hands="+p.getMainHandStack()+"/"+p.getOffHandStack()+" distance="+p.squaredDistanceTo(n));return p;}
 @GameTest(templateName="witchersbestiary:notice_board_arena",batchId="stage21b",tickLimit=40)
 public void inviteKnockoutRewardAndRematch(TestContext c){var n=npc(c,FistRegistry.NOVICE,3);var p=player(c,n);float health=p.getHealth(),npcHealth=n.getHealth();c.assertTrue(!FistFights.confirm(p,n),"Confirmation requires invitation");FistFights.invite(p,n);c.assertTrue(FistFights.confirm(p,n),"Confirmed bout");var a=FistFights.active(p);for(int i=0;i<60;i++)a.fight().tick();a.fight().opponent.health=1;a.fight().act(true,FistFightSession.Action.QUICK);for(int i=0;i<4;i++)a.fight().tick();a.fight().hit(true,true,true);FistFights.tick(p.getServer());c.assertTrue(FistFights.active(p)==null&&p.getInventory().count(com.witchersbestiary.economy.Currency.CROWN)==12,"First knockout pays once");c.assertTrue(p.getHealth()==health&&n.getHealth()==npcHealth&&n.isAlive(),"Virtual knockout changes no Minecraft health");p.getInventory().selectedSlot=1;FistFights.invite(p,n);c.assertTrue(FistFights.confirm(p,n),"Training rematch available");a=FistFights.active(p);for(int i=0;i<60;i++)a.fight().tick();a.fight().opponent.health=1;a.fight().act(true,FistFightSession.Action.QUICK);for(int i=0;i<4;i++)a.fight().tick();a.fight().hit(true,true,true);FistFights.tick(p.getServer());c.assertTrue(p.getInventory().count(com.witchersbestiary.economy.Currency.CROWN)==12,"No farm from rematch");var data=new net.minecraft.nbt.NbtCompound();n.writeCustomDataToNbt(data);var copy=FistRegistry.NOVICE.create(c.getWorld());copy.readCustomDataFromNbt(data);c.assertTrue(copy.pose().equals("idle"),"Transient fight pose resets; rewards live in personal server state");p.discard();n.discard();copy.discard();c.complete();}
 @GameTest(templateName="witchersbestiary:notice_board_arena",batchId="stage21b",tickLimit=40)
 public void independentFightsAndExternalDamage(TestContext c){var n=npc(c,FistRegistry.EXPERIENCED,3);var m=npc(c,FistRegistry.CHAMPION,12);var p=player(c,n);var q=player(c,m);FistFights.invite(p,n);c.assertTrue(FistFights.confirm(p,n),"First session");FistFights.invite(q,n);c.assertTrue(!FistFights.confirm(q,n),"NPC exclusive lock");FistFights.invite(q,m);c.assertTrue(FistFights.confirm(q,m),"Second independent session");c.assertTrue(!net.fabricmc.fabric.api.event.player.PlayerBlockBreakEvents.BEFORE.invoker().beforeBlockBreak(c.getWorld(),p,n.getBlockPos().down(),c.getWorld().getBlockState(n.getBlockPos().down()),null),"Participant cannot break arena blocks");float hp=n.getHealth();n.damage(c.getWorld().getDamageSources().playerAttack(p),1000);c.assertTrue(n.getHealth()==hp&&FistFights.active(p)!=null,"Vanilla weapon damage cannot bypass duel");var cancelled=FistFights.active(p).fight();FistFights.cancel(p);c.assertTrue(cancelled.stage==FistFightSession.Stage.CANCELLED,"Cancelled session exposes terminal state");c.assertTrue(FistFights.active(p)==null&&FistFights.active(q)!=null,"Cancellation isolated");m.damage(c.getWorld().getDamageSources().generic(),1);c.assertTrue(FistFights.active(q)==null&&m.getHealth()<40,"External damage ends fight and remains real damage");p.discard();q.discard();n.discard();m.discard();c.complete();}
 @GameTest(templateName="witchersbestiary:notice_board_arena",batchId="stage21b",tickLimit=40)
 public void defeatChunkUnloadAndPendingRewardPersistence(TestContext c){var n=npc(c,FistRegistry.CHAMPION,3);var p=player(c,n);FistFights.invite(p,n);FistFights.confirm(p,n);var f=FistFights.active(p).fight();for(int i=0;i<60;i++)f.tick();f.player.health=1;f.act(false,FistFightSession.Action.QUICK);for(int i=0;i<4;i++)f.tick();f.hit(false,true,true);float normal=p.getHealth();FistFights.tick(p.getServer());c.assertTrue(!f.playerWon&&p.getHealth()==normal&&!n.paid,"Defeat remains nonlethal and unpaid");FistFights.invite(p,n);FistFights.confirm(p,n);n.remove(net.minecraft.entity.Entity.RemovalReason.UNLOADED_TO_CHUNK);FistFights.tick(p.getServer());c.assertTrue(FistFights.active(p)==null,"Unloaded NPC releases player");var rewards=FistRewards.get(p.getServer());for(int i=0;i<36;i++)p.getInventory().setStack(i,new ItemStack(Items.STONE,64));rewards.reserve(p.getUuid(),28);c.assertTrue(!rewards.claim(p)&&rewards.pending(p.getUuid())==28,"Full bag keeps pending reward");var saved=rewards.writeNbt(new net.minecraft.nbt.NbtCompound(),c.getWorld().getRegistryManager());var restored=FistRewards.read(saved,c.getWorld().getRegistryManager());p.getInventory().setStack(0,new ItemStack(com.witchersbestiary.economy.Currency.WALLET));c.assertTrue(restored.claim(p)&&!restored.claim(p)&&com.witchersbestiary.economy.WalletTransactions.balance(p.getInventory().getStack(0))==28,"Pending sum persists and pays once into wallet");p.discard();c.complete();}
}
